#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string kthLuckyNumber(int k) {
        long long value = (long long)k + 1;
        string answer;
        while (value > 1) {
            answer.push_back((value & 1) ? '7' : '4');
            value >>= 1;
        }
        reverse(answer.begin(), answer.end());
        return answer;
    }
};
